package com.oms.dao;

import java.math.BigDecimal;
import java.sql.*;
import java.time.LocalDate;
import java.util.*;

public class WarehouseTransferDao {
 public record Option(long id,String code,String name){} public record Product(long id,String sku,String name,String unit){}
 public record Line(long productId,String sku,String product,String unit,BigDecimal sent,BigDecimal received){}
 public record Transfer(long id,String code,LocalDate date,long sourceId,String source,long destinationId,String destination,String note,String status,String reason,List<Line> items){}
 public record PageData(List<Option> warehouses,List<Product> products,List<Transfer> transfers){}
 public PageData page(Connection c)throws SQLException{return new PageData(warehouses(c),products(c),recent(c));}
 private List<Option> warehouses(Connection c)throws SQLException{List<Option>x=new ArrayList<>();try(var p=c.prepareStatement("SELECT id,code,name FROM warehouses WHERE status='ACTIVE' ORDER BY code");var r=p.executeQuery()){while(r.next())x.add(new Option(r.getLong(1),r.getString(2),r.getString(3)));}return x;}
 private List<Product> products(Connection c)throws SQLException{List<Product>x=new ArrayList<>();try(var p=c.prepareStatement("SELECT p.id,p.sku,p.name,u.name FROM products p JOIN units u ON u.id=p.base_unit_id WHERE p.status='ACTIVE' ORDER BY p.sku");var r=p.executeQuery()){while(r.next())x.add(new Product(r.getLong(1),r.getString(2),r.getString(3),r.getString(4)));}return x;}
 public List<Transfer> recent(Connection c)throws SQLException{List<Transfer>x=new ArrayList<>();try(var p=c.prepareStatement("SELECT t.id,t.code,t.transfer_date,t.source_warehouse_id,s.code,t.destination_warehouse_id,d.code,t.note,t.status,t.discrepancy_reason FROM warehouse_transfers t JOIN warehouses s ON s.id=t.source_warehouse_id JOIN warehouses d ON d.id=t.destination_warehouse_id ORDER BY t.id DESC LIMIT 30");var r=p.executeQuery()){while(r.next()){Transfer t=new Transfer(r.getLong(1),r.getString(2),r.getDate(3).toLocalDate(),r.getLong(4),r.getString(5),r.getLong(6),r.getString(7),r.getString(8),r.getString(9),r.getString(10),new ArrayList<>());loadLines(c,t);x.add(t);}}return x;}
 private void loadLines(Connection c,Transfer t)throws SQLException{try(var p=c.prepareStatement("SELECT l.product_id,p.sku,p.name,u.name,l.sent_quantity,l.received_quantity FROM warehouse_transfer_lines l JOIN products p ON p.id=l.product_id JOIN units u ON u.id=p.base_unit_id WHERE l.transfer_id=? ORDER BY l.id")){p.setLong(1,t.id());try(var r=p.executeQuery()){while(r.next())t.items().add(new Line(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getBigDecimal(5),r.getBigDecimal(6)));}}}
 public long next(Connection c)throws SQLException{long n;try(var p=c.prepareStatement("SELECT last_number FROM document_sequences WHERE name='WAREHOUSE_TRANSFER' FOR UPDATE");var r=p.executeQuery()){if(!r.next())throw new SQLException("Thiếu dãy phiếu chuyển kho");n=r.getLong(1)+1;}try(var p=c.prepareStatement("UPDATE document_sequences SET last_number=? WHERE name='WAREHOUSE_TRANSFER'")){p.setLong(1,n);p.executeUpdate();}return n;}
 public long insert(Connection c,String code,LocalDate date,long source,long destination,String note,long actor)throws SQLException{try(var p=c.prepareStatement("INSERT INTO warehouse_transfers(code,transfer_date,source_warehouse_id,destination_warehouse_id,note,created_by) VALUES(?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,code);p.setDate(2,java.sql.Date.valueOf(date));p.setLong(3,source);p.setLong(4,destination);p.setString(5,note);p.setLong(6,actor);p.executeUpdate();try(var r=p.getGeneratedKeys()){r.next();return r.getLong(1);}}}
 public void insertLine(Connection c,long id,long product,BigDecimal quantity)throws SQLException{try(var p=c.prepareStatement("INSERT INTO warehouse_transfer_lines(transfer_id,product_id,sent_quantity) VALUES(?,?,?)")){p.setLong(1,id);p.setLong(2,product);p.setBigDecimal(3,quantity);p.executeUpdate();}}
 public Transfer lock(Connection c,long id)throws SQLException{try(var p=c.prepareStatement("SELECT t.id,t.code,t.transfer_date,t.source_warehouse_id,s.code,t.destination_warehouse_id,d.code,t.note,t.status,t.discrepancy_reason FROM warehouse_transfers t JOIN warehouses s ON s.id=t.source_warehouse_id JOIN warehouses d ON d.id=t.destination_warehouse_id WHERE t.id=? FOR UPDATE")){p.setLong(1,id);try(var r=p.executeQuery()){if(!r.next())return null;Transfer t=new Transfer(r.getLong(1),r.getString(2),r.getDate(3).toLocalDate(),r.getLong(4),r.getString(5),r.getLong(6),r.getString(7),r.getString(8),r.getString(9),r.getString(10),new ArrayList<>());loadLines(c,t);return t;}}}
 public void send(Connection c,Transfer t,long actor)throws SQLException{for(Line l:t.items()){try(var p=c.prepareStatement("UPDATE warehouse_inventory SET on_hand=on_hand-? WHERE warehouse_id=? AND product_id=? AND on_hand-reserved>=?")){p.setBigDecimal(1,l.sent());p.setLong(2,t.sourceId());p.setLong(3,l.productId());p.setBigDecimal(4,l.sent());if(p.executeUpdate()!=1)throw new IllegalStateException("Tồn khả dụng không đủ cho "+l.sku()+".");}movement(c,t.sourceId(),l.productId(),l.sent(),"TRANSFER_OUT",t.id(),actor);}try(var p=c.prepareStatement("UPDATE warehouse_transfers SET status='IN_TRANSIT',sent_at=CURRENT_TIMESTAMP WHERE id=? AND status='DRAFT'")){p.setLong(1,t.id());p.executeUpdate();}}
 public void receive(Connection c,Transfer t,List<BigDecimal> quantities,String reason,long actor)throws SQLException{boolean diff=false;for(int i=0;i<t.items().size();i++){Line l=t.items().get(i);BigDecimal q=quantities.get(i);diff|=q.compareTo(l.sent())!=0;try(var p=c.prepareStatement("UPDATE warehouse_transfer_lines SET received_quantity=? WHERE transfer_id=? AND product_id=?")){p.setBigDecimal(1,q);p.setLong(2,t.id());p.setLong(3,l.productId());p.executeUpdate();}if(q.signum()>0){try(var p=c.prepareStatement("INSERT INTO warehouse_inventory(warehouse_id,product_id,on_hand,reserved) VALUES(?,?,?,0) ON DUPLICATE KEY UPDATE on_hand=on_hand+VALUES(on_hand)")){p.setLong(1,t.destinationId());p.setLong(2,l.productId());p.setBigDecimal(3,q);p.executeUpdate();}movement(c,t.destinationId(),l.productId(),q,"TRANSFER_IN",t.id(),actor);}}try(var p=c.prepareStatement("UPDATE warehouse_transfers SET status=?,discrepancy_reason=?,received_by=?,received_at=CURRENT_TIMESTAMP WHERE id=? AND status='IN_TRANSIT'")){p.setString(1,diff?"DISCREPANCY":"RECEIVED");p.setString(2,reason);p.setLong(3,actor);p.setLong(4,t.id());p.executeUpdate();}}
 private void movement(Connection c,long warehouse,long product,BigDecimal qty,String type,long ref,long actor)throws SQLException{try(var p=c.prepareStatement("INSERT INTO inventory_movements(warehouse_id,product_id,unit_id,quantity,movement_type,reference_type,reference_id,created_by) SELECT ?,id,base_unit_id,?,?, 'WAREHOUSE_TRANSFER',?,? FROM products WHERE id=?")){p.setLong(1,warehouse);p.setBigDecimal(2,qty);p.setString(3,type);p.setLong(4,ref);p.setLong(5,actor);p.setLong(6,product);p.executeUpdate();}}
}
